from __future__ import annotations

import itertools
from typing import Any, Iterator

def chunked_stream(data: Iterator[dict[str, Any]], chunk_size: int = 50) -> Iterator[list[dict[str, Any]]]:
    """Stream collection in bounded memory chunks using itertools.islice."""
    while True:
        chunk = list(itertools.islice(data, chunk_size))
        if not chunk:
            break
        yield chunk

def filter_active_records(records: Iterator[dict[str, Any]]) -> Iterator[dict[str, Any]]:
    """Pure functional filtering pipeline for articles."""
